func apDpi() int32 {
	return 300
}

func apPutWord(t *strings.Builder, etext *port.Cells, arr *port.Cells, stride int32, row int32) int32 {
	var ts int32 = port.CellsAt(arr, (row*stride)+evidence.HdTstart())
	var tl int32 = port.CellsAt(arr, (row*stride)+evidence.HdTlen())
	var k int32 = 0
	for k < tl {
		port.TextCp(t, port.CellsAt(etext, ts+k))
		k += 1
	}
	return 0
}

func apPutBox(t *strings.Builder, arr *port.Cells, stride int32, row int32) int32 {
	// `[x0,y0,x1,y1]` in whole points (the head's box, centipoints over 100).
	port.TextAscii(t, "[")
	port.TextI32(t, port.CellsAt(arr, (row*stride)+evidence.HdX0())/100)
	port.TextAscii(t, ",")
	port.TextI32(t, port.CellsAt(arr, (row*stride)+evidence.HdY0())/100)
	port.TextAscii(t, ",")
	port.TextI32(t, port.CellsAt(arr, (row*stride)+evidence.HdX1())/100)
	port.TextAscii(t, ",")
	port.TextI32(t, port.CellsAt(arr, (row*stride)+evidence.HdY1())/100)
	port.TextAscii(t, "]")
	return 0
}

func apPutRun(t *strings.Builder, etext *port.Cells, refs *port.Cells, words *port.Cells, owords *port.Cells, first int32, cnt int32) int32 {
	// The words of a run of `refs`, joined by a space.
	var k int32 = 0
	var ea int32 = 0
	var row int32 = 0
	for k < cnt {
		if k > 0 {
			port.TextAscii(t, " ")
		}
		ea = port.CellsAt(refs, (first+k)*2)
		row = port.CellsAt(refs, ((first+k)*2)+1)
		if ea == evidence.EaOwords() {
			apPutWord(t, etext, owords, 28, row)
			apPutBox(t, owords, 28, row)
		} else {
			apPutWord(t, etext, words, 24, row)
			apPutBox(t, words, 24, row)
		}
		k += 1
	}
	return 0
}

func apFont(refs *port.Cells, words *port.Cells, first int32, cnt int32) int32 {
	// The font of the first text-layer word of a run of `refs`, -1 for an empty run.
	if cnt <= 0 {
		return -1
	}
	var row int32 = port.CellsAt(refs, (first*2)+1)
	return port.CellsAt(words, (row*24)+evidence.WfFont())
}

func apDump(t *strings.Builder, etext *port.Cells, refs *port.Cells, words *port.Cells, owords *port.Cells, cg *port.Cells) int32 {
	var n int32 = player.CgCount(cg)
	var g int32 = 0
	var v int32 = 0
	for g < n {
		v = port.CellsAt(cg, g*16)
		port.TextAscii(t, "g")
		port.TextI32(t, g)
		port.TextAscii(t, " p")
		port.TextI32(t, v)
		port.TextAscii(t, " t")
		port.TextI32(t, player.CgGet(cg, g, player.CgfTcount()))
		port.TextAscii(t, " o")
		port.TextI32(t, player.CgGet(cg, g, player.CgfOcount()))
		port.TextAscii(t, " h")
		port.TextI32(t, player.CgGet(cg, g, player.CgfHcount()))
		port.TextAscii(t, " f")
		port.TextI32(t, player.CgGet(cg, g, player.CgfFlags()))
		port.TextAscii(t, " s")
		port.TextI32(t, player.CgGet(cg, g, player.CgfSim()))
		port.TextAscii(t, " c")
		port.TextI32(t, player.CgGet(cg, g, player.CgfSimfold()))
		port.TextAscii(t, " l")
		port.TextI32(t, player.CgGet(cg, g, player.CgfTline()))
		port.TextAscii(t, " n")
		port.TextI32(t, apFont(refs, words, player.CgGet(cg, g, player.CgfTfirst()), player.CgGet(cg, g, player.CgfTcount())))
		port.TextAscii(t, " | T ")
		if player.CgGet(cg, g, player.CgfTcount()) > 0 {
			apPutRun(t, etext, refs, words, owords, player.CgGet(cg, g, player.CgfTfirst()), player.CgGet(cg, g, player.CgfTcount()))
		}
		port.TextAscii(t, " | O ")
		if player.CgGet(cg, g, player.CgfOcount()) > 0 {
			apPutRun(t, etext, refs, words, owords, player.CgGet(cg, g, player.CgfOfirst()), player.CgGet(cg, g, player.CgfOcount()))
		}
		port.TextAscii(t, " | H ")
		if player.CgGet(cg, g, player.CgfHcount()) > 0 {
			apPutRun(t, etext, refs, words, owords, player.CgGet(cg, g, player.CgfHfirst()), player.CgGet(cg, g, player.CgfHcount()))
		}
		port.TextCp(t, 10)
		g += 1
	}
	return 0
}

